// Add helper to check if an error is retryable
export function isRetryableError(error) {
    // Network errors, connection timeouts, and other temporary issues
    if (error instanceof RetryableAttemptError)
        return true;
    const lowerCaseMessage = error.message?.toLowerCase() || '';
    return (lowerCaseMessage.includes('network connection lost') ||
        lowerCaseMessage.includes('failed to fetch') ||
        lowerCaseMessage.includes('network request failed') ||
        lowerCaseMessage.includes('timeout') ||
        lowerCaseMessage.includes('fetch failed') ||
        lowerCaseMessage.includes('econnrefused') ||
        lowerCaseMessage.includes('econnreset'));
}
export class RetryableAttemptError extends Error {
    retryAfterMs;
    data;
    constructor(message, retryAfterMs, data) {
        super(message);
        this.retryAfterMs = retryAfterMs;
        this.data = data;
    }
}
export class UnretryableAttemptError extends Error {
}
export class RetriedError extends Error {
    attempt;
    data;
    constructor(error, attempt) {
        super(error.message);
        this.attempt = attempt;
        this.name = error.name;
        this.stack = error.stack;
        this.cause = error.cause;
        this.data = error.data;
    }
}
// Status codes that should trigger a retry
const RETRYABLE_STATUS_CODES = new Set([408, 429, 500, 502, 503, 504, 520]);
export function isRetryableStatusCode(status) {
    return RETRYABLE_STATUS_CODES.has(status);
}
export const defaultAssertRetryableResponse = async ({ response, retryAfterMs }) => {
    if (isRetryableStatusCode(response.status)) {
        return {
            retryable: true,
            retryAfterMs,
            errorMessage: `Retryable HTTP status code: ${response.status}`,
            errorDetails: await formatResponse(response),
        };
    }
    if (typeof retryAfterMs === 'number') {
        return {
            retryable: true,
            retryAfterMs,
            errorMessage: `Retryable HTTP status code: ${response.status}`,
            errorDetails: await formatResponse(response),
        };
    }
};
export async function formatResponse(response) {
    const text = await response.text();
    response.text = async () => text;
    try {
        const json = JSON.parse(text);
        response.json = async () => json;
        return json;
    }
    catch {
        return {
            text,
        };
    }
}
